package com.bbb.exercise.agentdemo1_0.model;
import org.springframework.stereotype.Component; import java.util.*;
@Component public final class ModelProviderRegistry {
 private final Map<ModelProvider,ProviderDescriptor> descriptors; public ModelProviderRegistry(){this(defaultRegistry().descriptors);} public ModelProviderRegistry(Map<ModelProvider,ProviderDescriptor> d){descriptors=Map.copyOf(d);}
 public static ModelProviderRegistry defaultRegistry(){EnumMap<ModelProvider,ProviderDescriptor> v=new EnumMap<>(ModelProvider.class);v.put(ModelProvider.GPT,descriptor(ModelProvider.GPT,true,"https://api.openai.com/v1",ModelCapability.CHAT,ModelCapability.VISION,ModelCapability.IMAGE,ModelCapability.EMBEDDING));v.put(ModelProvider.GEMINI,descriptor(ModelProvider.GEMINI,true,"https://generativelanguage.googleapis.com/v1beta/openai/",ModelCapability.CHAT,ModelCapability.VISION,ModelCapability.EMBEDDING));v.put(ModelProvider.QWEN,descriptor(ModelProvider.QWEN,true,"https://dashscope.aliyuncs.com/compatible-mode/v1",ModelCapability.CHAT,ModelCapability.VISION,ModelCapability.IMAGE,ModelCapability.EMBEDDING));v.put(ModelProvider.GLM,descriptor(ModelProvider.GLM,true,"https://open.bigmodel.cn/api/paas/v4",ModelCapability.CHAT,ModelCapability.VISION,ModelCapability.IMAGE,ModelCapability.EMBEDDING));v.put(ModelProvider.HY,descriptor(ModelProvider.HY,true,"https://api.hunyuan.cloud.tencent.com/v1",ModelCapability.CHAT,ModelCapability.VISION,ModelCapability.IMAGE,ModelCapability.EMBEDDING));return new ModelProviderRegistry(v);}
 public Set<ModelProvider> providers(){return descriptors.keySet();} public ProviderDescriptor resolve(ModelProvider p,ModelCapability c,String model){if(p==null||c==null)throw new IllegalArgumentException("Provider 和模型能力不能为空");ProviderDescriptor d=descriptors.get(p);if(d==null||!d.capabilities().contains(c))throw new IllegalArgumentException("Provider "+p+" 不支持模型能力 "+c);if(model==null||model.isBlank())throw new IllegalArgumentException("模型名称不能为空");return d;}
 private static ProviderDescriptor descriptor(ModelProvider p,boolean compatible,String url,ModelCapability... c){return new ProviderDescriptor(p,EnumSet.copyOf(Set.of(c)),compatible,url);} public record ProviderDescriptor(ModelProvider provider,Set<ModelCapability> capabilities,boolean openAiCompatible,String defaultBaseUrl){public ProviderDescriptor{capabilities=Set.copyOf(capabilities);}}
}
